static size_t compare(const void*a,const void*b,size_t n,size_t word,const char*name){for(size_t i=0;i<n;++i)if(memcmp((const char*)a+i*word,(const char*)b+i*word,word)){fprintf(stderr,"%s word%zu mismatch\n",name,i);exit(3);}return n;}
